void bn_read_bin(bn_t a, const uint8_t *bin, int len) {
        int i, j;
        dig_t d = (RLC_DIG / 8);
        int digs = (len % d == 0 ? len / d : len / d + 1);

        bn_grow(a, digs);
        bn_zero(a);
        a->used = digs;

        for (i = 0; i < digs - 1; i++) {
                d = 0;
                for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
                        d = d << 8;
                        d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
                }
                a->dp[i] = d;
        }
        d = 0;
        for (j = (RLC_DIG / 8) - 1; j >= 0; j--) {
                if ((int)(i * (RLC_DIG / 8) + j) < len) {
                        d = d << 8;
                        d |= bin[len - 1 - (i * (RLC_DIG / 8) + j)];
                }
        }
        a->dp[i] = d;

        a->sign = RLC_POS;
        bn_trim(a);
}

void bn_write_bin(uint8_t *bin, int len, const bn_t a) {
        int size, k;
        dig_t d;

        size = bn_size_bin(a);

        if (len < size) {
                RLC_THROW(ERR_NO_BUFFER);
                return;
        }

        k = 0;
        for (int i = 0; i < a->used - 1; i++) {
                d = a->dp[i];
                for (int j = 0; j < (int)(RLC_DIG / 8); j++) {
                        bin[len - 1 - k++] = d & 0xFF;
                        d = d >> 8;
                }
        }

        d = a->dp[a->used - 1];
        while (d != 0) {
                bin[len - 1 - k++] = d & 0xFF;
                d = d >> 8;
        }

        while (k < len) {
                bin[len - 1 - k++] = 0;
        }
}

int bn_size_raw(const bn_t a) {
        return a->used;
}

void bn_read_raw(bn_t a, const dig_t *raw, int len) {
        RLC_TRY {
                bn_grow(a, len);
                a->used = len;
                a->sign = RLC_POS;
                dv_copy(a->dp, raw, len);
                bn_trim(a);
        } RLC_CATCH_ANY {
                RLC_THROW(ERR_CAUGHT);
        }
}

void bn_write_raw(dig_t *raw, int len, const bn_t a) {
        int i, size;

        size = a->used;

        if (len < size) {
                RLC_THROW(ERR_NO_BUFFER);
                return;
        }

        for (i = 0; i < size; i++) {
                raw[i] = a->dp[i];
        }
        for (; i < len; i++) {
                raw[i] = 0;
        }
}
